using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the user answer to a poll. A poll in quiz mode can be answered only once
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetPollAnswerAsync(long chatId = default, long messageId = default, int[] optionIds = default)
    {

           using var activity =  StartCallActivity("SetPollAnswerAsync", typeof(SetPollAnswer).FullName ?? "SetPollAnswerAsync");

           try
           {
             return client.SetPollAnswerAsync(chatId, messageId, optionIds);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
